class Solution {
    public String reverseLetters(String text) {
        StringBuilder letters = new StringBuilder();
        for (char c : text.toCharArray()) if (Character.isLetter(c)) letters.append(c);
        StringBuilder out = new StringBuilder();
        int k = letters.length() - 1;
        for (char c : text.toCharArray()) out.append(Character.isLetter(c) ? letters.charAt(k--) : c);
        return out.toString();
    }
}

