#include <ctype.h>

char* reverseLetters(char* text) {
    int n = strlen(text), m = 0;
    char* letters = malloc(n + 1);
    for (int i = 0; i < n; i++) if (isalpha((unsigned char) text[i])) letters[m++] = text[i];
    char* out = malloc(n + 1);
    for (int i = 0; i < n; i++) out[i] = isalpha((unsigned char) text[i]) ? letters[--m] : text[i];
    out[n] = '\0';
    free(letters);
    return out;
}

