class Solution {
    public String reverseLetters(String text) {
        char[] a = text.toCharArray();
        int i = 0, j = a.length - 1;
        while (i < j) {
            if (!Character.isLetter(a[i])) i++;
            else if (!Character.isLetter(a[j])) j--;
            else { char t = a[i]; a[i++] = a[j]; a[j--] = t; }
        }
        return new String(a);
    }
}

